import React from "react";
import { useNavigate, useLocation } from "react-router-dom";

function Layout({
  children,
  filter,
  setFilter,
  category,
  setCategory,
  search,
  setSearch,
}) {
  const navigate = useNavigate();
  const location = useLocation();

  const user = JSON.parse(localStorage.getItem("user") || "null");

  const handleLogout = () => {
    localStorage.removeItem("user");
    navigate("/login");
  };

  return (
    <div className="layout">

      {/* ================= NAVBAR ================= */}
      <header className="navbar">

        <div
          className="brand"
          onClick={() => navigate("/dashboard")}
        >
          <div className="logo">C</div>

          <div>
            <h3>Campus Connect</h3>
            <span>Student Learning Hub</span>
          </div>
        </div>

        {/* SEARCH */}
        <div className="search-container">
          <span className="search-icon">🔍</span>

          <input
            type="text"
            placeholder="Search questions, notes & topics..."
            value={search || ""}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        {/* USER */}
        <div className="navbar-user">

          <div className="avatar">
            {user?.name?.[0]?.toUpperCase() || "U"}
          </div>

          <div className="navbar-user-info">
            <strong>{user?.name || "User"}</strong>
            <span>{user?.role || "Student"}</span>
          </div>

          <button
            className="logout-icon"
            onClick={handleLogout}
            title="Logout"
          >
            ↪
          </button>

        </div>

      </header>


      {/* ================= BODY ================= */}
      <div className="app-body">

        {/* ================= SIDEBAR ================= */}
        <aside className="filter-sidebar">

          <div className="filter-card">

            <h3>
              ⚱ Filters
            </h3>

            {/* SORT */}
            <div className="filter-section">

              <p className="filter-heading">
                Sort By
              </p>

              <button
                className={`filter-option ${
                  filter === "recent" ? "selected" : ""
                }`}
                onClick={() => setFilter("recent")}
              >
                🕐 Recent
              </button>

              <button
                className={`filter-option ${
                  filter === "popular" ? "selected" : ""
                }`}
                onClick={() => setFilter("popular")}
              >
                ↗ Popular
              </button>

            </div>


            {/* CATEGORY */}
            <div className="filter-section">

              <p className="filter-heading">
                Category
              </p>

              <button
                className={`filter-option ${
                  category === "all" ? "selected" : ""
                }`}
                onClick={() => setCategory("all")}
              >
                All Posts
              </button>

              <button
                className={`filter-option ${
                  category === "notes" ? "selected" : ""
                }`}
                onClick={() => setCategory("notes")}
              >
                Study Notes
              </button>

              <button
                className={`filter-option ${
                  category === "projects" ? "selected" : ""
                }`}
                onClick={() => setCategory("projects")}
              >
                Projects
              </button>

              <button
                className={`filter-option ${
                  category === "guidance" ? "selected" : ""
                }`}
                onClick={() => setCategory("guidance")}
              >
                Guidance
              </button>

              <button
                className={`filter-option ${
                  category === "career" ? "selected" : ""
                }`}
                onClick={() => setCategory("career")}
              >
                Career
              </button>

              <button
                className={`filter-option ${
                  category === "skills" ? "selected" : ""
                }`}
                onClick={() => setCategory("skills")}
              >
                Skills
              </button>

            </div>

          </div>


          {/* SIDEBAR NAVIGATION */}
          <div className="sidebar-navigation">

            <button
              onClick={() => navigate("/dashboard")}
              className={location.pathname === "/dashboard" ? "active" : ""}
            >
              🏠 Dashboard
            </button>

            <button
              onClick={() => navigate("/profile")}
              className={location.pathname === "/profile" ? "active" : ""}
            >
              👤 Profile
            </button>

            <button
              onClick={() => navigate("/notes")}
              className={location.pathname === "/notes" ? "active" : ""}
            >
              📚 My Notes
            </button>

          </div>

        </aside>


        {/* ================= MAIN CONTENT ================= */}
        <main className="main-content">
          {children}
        </main>

      </div>

    </div>
  );
}

export default Layout;
